import { render } from '@solidjs/web';
import { createSignal } from 'solid-js';

const names = { ada: 'Ada Lovelace', grace: 'Grace Hopper', alan: 'Alan Turing' };

function App() {
  const [person, setPerson] = createSignal('ada');
  const [badge, setBadge] = createSignal('Ada Lovelace');

  return (
    <>
      <label>
        Person{' '}
        <select onChange={(event) => setPerson(event.currentTarget.value)}>
          <option value="ada">Ada</option>
          <option value="grace">Grace</option>
          <option value="alan">Alan</option>
        </select>
      </label>
      <p>
        <label>
          Badge name{' '}
          <input
            value={badge()}
            onInput={(event) => setBadge(event.currentTarget.value)}
          />
        </label>
      </p>
      <p>Badge: {badge()}</p>
    </>
  );
}

render(() => <App />, document.getElementById('app'));

import { render } from '@solidjs/web';
import { createSignal } from 'solid-js';

const names = { ada: 'Ada Lovelace', grace: 'Grace Hopper', alan: 'Alan Turing' };

function App() {
  const [person, setPerson] = createSignal('ada');
  const [badge, setBadge] = createSignal(() => names[person()]);

  return (
    <>
      <label>
        Person{' '}
        <select onChange={(event) => setPerson(event.currentTarget.value)}>
          <option value="ada">Ada</option>
          <option value="grace">Grace</option>
          <option value="alan">Alan</option>
        </select>
      </label>
      <p>
        <label>
          Badge name{' '}
          <input
            value={badge()}
            onInput={(event) => setBadge(event.currentTarget.value)}
          />
        </label>
      </p>
      <p>Badge: {badge()}</p>
    </>
  );
}

render(() => <App />, document.getElementById('app'));
